mapper.select:
SELECT o.*
FROM orders o
WHERE o.id = #{id}

SELECT o.* FROM orders o INNER JOIN users u ON o.user_id = u.id LEFT JOIN ( SELECT order_id, SUM(subtotal) AS item_total FROM order_items GROUP BY order_id ) oi_sum ON o.id = oi_sum.order_id WHERE 1 = 1
AND o.user_id = #{userId}
AND o.status = #{status}
AND (o.order_code LIKE CONCAT('%', #{keyword}, '%') OR u.username LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY o.ordered_at DESC
